def test_phase157_r5_r4_generic_filter_applies_without_representative_target_guard():
  root_step = _step(
    "Phase157 R5-R4 arbitrary root",
    None,
    "arbitrary non-representative target",
  )

  fixed_step = _step(
    'Toda 4.5 stable-range iterated suspension isomorphism',
    '(4.5)',
    "fixed candidate",
  )
  internal_step = _step(
    'Toda 4.5 pi_4^3 finite-cyclic transport',
    '(4.5)',
    "proof-internal candidate",
  )
  aggregate_step = _step(
    'Toda Proposition 5.3 finite-dimensional integration',
    'Proposition 5.3',
    "aggregate fixed statement without component",
  )

  fixed_entry = TodaGroupProofNarrativeReferenceEntry(
    number=1,
    reference=_reference(
      '(4.5)'
    ),
    proof_steps=(
      fixed_step,
    ),
  )
  internal_entry = TodaGroupProofNarrativeReferenceEntry(
    number=2,
    reference=_reference(
      '(4.5)'
    ),
    proof_steps=(
      internal_step,
    ),
  )
  aggregate_entry = TodaGroupProofNarrativeReferenceEntry(
    number=3,
    reference=_reference(
      'Proposition 5.3'
    ),
    proof_steps=(
      aggregate_step,
    ),
  )

  filtered = (
    filter_toda_group_proof_narrative_reference_entries_by_fixed_statement_boundary(
      (
        fixed_entry,
        internal_entry,
        aggregate_entry,
      ),
      root_step,
    )
  )

  assert len(
    filtered
  ) == 1
  assert filtered[
    0
  ].number == 1
  assert filtered[
    0
  ].proof_steps == (
    fixed_step,
  )

def test_phase148_rc2_4_repair_r4_1_r1_argument_locations_use_current_argument_api():
  module = (
    _load_audit_module()
  )
  group_result = (
    module._group_result()
  )
  contexts = (
    module._contexts(
      group_result
    )
  )
  complete = contexts[
    "complete"
  ]
  matches = (
    module._matching_steps(
      complete[
        "closure"
      ],
      module.EQUATIONS[
        0
      ][
        1
      ],
    )
  )

  assert len(
    matches
  ) == 1

  proof_step = matches[
    0
  ][
    0
  ].proof_step

  locations = (
    module._argument_locations(
      complete[
        "closure"
      ],
      complete[
        "sidecar"
      ],
      complete[
        "arguments"
      ],
      complete[
        "blocks"
      ],
      proof_step,
    )
  )

  assert isinstance(
    locations,
    tuple,
  )

  for (
    argument_index,
    role,
    location,
  ) in locations:
    assert isinstance(
      argument_index,
      int,
    )
    assert isinstance(
      role,
      str,
    )
    assert set(
      location
    ) == {
      "supporting",
      "conclusion",
      "local_body",
    }

def test_phase78_actual_steps_register_and_retrieve_without_graph_changes():
  from test_phase78_stable_g0_to_g7_integration import (
    build_phase78_11_data,
  )

  data = build_phase78_11_data()
  repository = ProofRepository()

  g7_step = data[
    "g7_step"
  ]
  aggregate_step = data[
    "aggregate_step"
  ]

  g7_entry = ProofRepositoryEntry(
    key="phase78.g7",
    step=g7_step,
    phase="78",
    theorem=(
      "Toda stable G_0 through G_7 integration"
    ),
  )
  aggregate_entry = ProofRepositoryEntry(
    key="phase78.stable_g0_to_g7",
    step=aggregate_step,
    phase="78",
    theorem=(
      "Toda stable G_0 through G_7 integration"
    ),
  )

  repository.register(
    g7_entry
  )
  repository.register(
    aggregate_entry
  )

  assert (
    repository.get(
      "phase78.g7"
    ).step
    is g7_step
  )

  assert (
    repository.get(
      "phase78.stable_g0_to_g7"
    ).step
    is aggregate_step
  )

  assert (
    repository.find_by_conclusion(
      g7_step.conclusion
    )
    == (
      g7_entry,
    )
  )

  assert (
    repository.find_by_phase(
      "78"
    )
    == (
      g7_entry,
      aggregate_entry,
    )
  )

  dependencies = repository.dependencies(
    aggregate_entry
  )

  assert (
    dependencies
    == data[
      "premise_steps"
    ]
  )

  assert all(
    actual is expected
    for actual, expected in zip(
      dependencies,
      data[
        "premise_steps"
      ],
    )
  )
